import java.util.Arrays;

public class Grids {
    static int sum(int[] values) {
        int total = 0;
        for (int i = 0; i < values.length; i++) total += values[i];   // strictly below length.
        return total;                                                // empty: 0.
    }

    static int countSeats(int[][] seats) {
        int count = 0;
        for (int r = 0; r < seats.length; r++)
            for (int c = 0; c < seats[r].length; c++)                // this row's length.
                if (seats[r][c] == 1) count++;
        return count;
    }

    public static void main(String[] args) {
        System.out.println(sum(new int[0]));                       // 0
        int[][] seats = { {1, 0, 1, 1}, {0, 1} };                   // jagged: 4 and 2.
        System.out.println(countSeats(seats));                      // 4
        System.out.println(Arrays.deepToString(seats));             // [[1, 0, 1, 1], [0, 1]]
        int[] copy = Arrays.copyOf(seats[0], 4);                    // independent copy.
        System.out.println(Arrays.equals(copy, seats[0]));          // true
    }
}
```

| Need | Tool |
|---|---|
| print. | `Arrays.toString`, `deepToString`. |
| sort. | `Arrays.sort`. |
| copy. | `Arrays.copyOf`, `clone()`. |
| compare contents. | `Arrays.equals` (not ==). |

